"""Owned native admission/read-authority probe; all payloads are synthetic."""
import ast
import copy
from datetime import datetime, timezone
import json
import os
from pathlib import Path
import re
import sys
import time
import uuid
sys.path.insert(0, str(Path.cwd() / 'scripts/aws'))
from aws_cli import run, result

ACCOUNT = '000000000000'
REGION = 'us-west-2'
PREFIX = 'sd-sfn-encadm-' + uuid.uuid4().hex[:10]
DEST = Path('testdata/aws/stepfunctions/encryption_admission.json')
SOURCE = Path('/tmp/sfn_encryption_admission_probe.py')
ENV = dict(os.environ, AWS_PROFILE='default', AWS_REGION=REGION, AWS_DEFAULT_REGION=REGION, AWS_MAX_ATTEMPTS='1', AWS_RETRY_MODE='standard', AWS_PAGER='')
ENVS = {'default': ENV}
OWNED = {'keys': [], 'aliases': [], 'roles': [], 'machines': [], 'activities': [], 'executions': []}
CAP = {'account': ACCOUNT, 'region': REGION, 'prefix': PREFIX, 'caller_arn': None, 'started_at': datetime.now(timezone.utc).isoformat(), 'observations': [], 'actors': {}, 'owned_resources': OWNED, 'notes': [], 'references': ['https://docs.aws.amazon.com/step-functions/latest/dg/encryption-at-rest.html', 'https://docs.aws.amazon.com/step-functions/latest/apireference/API_EncryptionConfiguration.html', 'https://docs.aws.amazon.com/step-functions/latest/apireference/API_CreateStateMachine.html', 'https://docs.aws.amazon.com/step-functions/latest/apireference/API_CreateActivity.html', 'https://docs.aws.amazon.com/step-functions/latest/apireference/API_UpdateStateMachine.html', 'https://docs.aws.amazon.com/step-functions/latest/apireference/API_DescribeStateMachine.html', 'https://docs.aws.amazon.com/step-functions/latest/apireference/API_DescribeStateMachineForExecution.html'], 'source': [], 'cleanup': {}, 'protocol': {'automatic_retries': 0, 'request_timeout_seconds': 45, 'account_settings_modified': False, 'asymmetric_key_exception': 'Parent approved a third short-lived RSA_2048 CMK for non-symmetric admission rejection, in addition to two symmetric keys required by retained-definition controls.', 'actor_controls': 'One newly created immutable IAM role per caller policy, identical inline session policy on AssumeRole, no policy mutations after setup. Credentials remain only in process memory.'}}
KEYS = {}
ARNS = {}
BASE_DEF = json.dumps({'StartAt': 'Synthetic', 'States': {'Synthetic': {'Type': 'Pass', 'Result': {'probe': 'admission-old'}, 'End': True}}}, separators=(',', ':'))
NEW_DEF = json.dumps({'StartAt': 'Synthetic', 'States': {'Synthetic': {'Type': 'Pass', 'Result': {'probe': 'admission-new'}, 'End': True}}}, separators=(',', ':'))
MAP_DEF = json.dumps({'StartAt': 'Batch', 'States': {'Batch': {'Type': 'Map', 'Label': 'NativeLabel', 'ItemsPath': '$.items', 'MaxConcurrency': 1, 'ItemProcessor': {'ProcessorConfig': {'Mode': 'DISTRIBUTED', 'ExecutionType': 'STANDARD'}, 'StartAt': 'Item', 'States': {'Item': {'Type': 'Pass', 'End': True}}}, 'End': True}}}, separators=(',', ':'))


def save():
    CAP['source'] = [{'path': str(SOURCE), 'content': SOURCE.read_text()}, {'path': 'scripts/aws/aws_cli.py', 'content': Path('scripts/aws/aws_cli.py').read_text()}]
    DEST.write_text(json.dumps(CAP, indent=2) + '\n')


def redact(value):
    if isinstance(value, dict):
        return {k: '[REDACTED]' if k.lower() in ('accesskeyid', 'secretaccesskey', 'sessiontoken', 'plaintext', 'ciphertextblob') else redact(v) for k, v in value.items()}
    if isinstance(value, list):
        return [redact(v) for v in value]
    return value


def call(label, service, operation, params=None, actor='default'):
    params = params or {}
    started = int(time.time() * 1000)
    proc = run(service, operation, params, ENVS[actor], options=['--debug', '--cli-connect-timeout', '10', '--cli-read-timeout', '30', '--no-paginate'], timeout=45)
    decoded = result(proc, debug=True, cli_message=None)
    headers = {}
    lines = proc.stderr.splitlines()
    for n, line in enumerate(lines):
        if 'Response headers: ' in line:
            try:
                headers = ast.literal_eval(line.split('Response headers: ', 1)[1])
            except (ValueError, SyntaxError):
                pass
        if 'Response body:' in line and n + 1 < len(lines) and lines[n + 1].startswith(('b\'', 'b"')):
            try:
                body = json.loads(ast.literal_eval(lines[n + 1]))
                if proc.returncode:
                    decoded['output'] = body
            except (ValueError, SyntaxError):
                pass
    decoded.setdefault('output', {})
    decoded['request_id'] = next((v for k, v in headers.items() if k.lower() in ('x-amzn-requestid', 'x-amz-request-id')), None)
    raw = copy.deepcopy(decoded)
    if service == 'cloudtrail' and decoded['code'] == 'Success':
        events = decoded['output'].get('Events', [])
        decoded['output']['Events'] = [dict(e, CloudTrailEvent=redact(json.loads(e['CloudTrailEvent']))) for e in events]
    decoded = redact(decoded)
    CAP['observations'].append({'label': label, 'service': service, 'operation': operation, 'actor': actor, 'region': REGION, 'input': params, 'request_started_ms': started, 'request_finished_ms': int(time.time() * 1000), 'result': decoded})
    save()
    print(label + ': ' + decoded['code'], flush=True)
    return raw


def must(response):
    if response['code'] != 'Success':
        raise RuntimeError('Required probe setup failed: ' + response['code'] + ' ' + response.get('message', ''))
    return response['output']


def enc(key='old', reuse=None):
    value = {'type': 'CUSTOMER_MANAGED_KMS_KEY', 'kmsKeyId': KEYS[key]['Arn'] if key in KEYS else key}
    if reuse is not None:
        value['kmsDataKeyReusePeriodSeconds'] = reuse
    return value


def create(label, config=None, actor='default', kind='STANDARD', name=None, definition=None, publish=False):
    name = name or PREFIX + '-' + label
    params = {'name': name}
    if kind != 'ACTIVITY':
        params.update(definition=definition or BASE_DEF, roleArn=ARNS['execution_role'], type=kind)
        if publish:
            params['publish'] = True
    if config is not None:
        params['encryptionConfiguration'] = config
    response = call(label, 'stepfunctions', 'create-activity' if kind == 'ACTIVITY' else 'create-state-machine', params, actor)
    if response['code'] == 'Success':
        field = 'activityArn' if kind == 'ACTIVITY' else 'stateMachineArn'
        arn = response['output'][field]
        bucket = OWNED['activities' if kind == 'ACTIVITY' else 'machines']
        if arn not in bucket:
            bucket.append(arn)
        ARNS[label] = arn
        save()
    return response


def describe(label, arn, actor='default', included=None, execution=False):
    params = {'executionArn' if execution else 'stateMachineArn': arn}
    if included is not None:
        params['includedData'] = included
    return call(label, 'stepfunctions', 'describe-state-machine-for-execution' if execution else 'describe-state-machine', params, actor)


def role(name, principal, policy):
    role_name = PREFIX + '-' + name
    trust = {'Version': '2012-10-17', 'Statement': [{'Effect': 'Allow', 'Principal': principal, 'Action': 'sts:AssumeRole'}]}
    output = must(call('setup-role-' + name, 'iam', 'create-role', {'RoleName': role_name, 'AssumeRolePolicyDocument': json.dumps(trust), 'Description': 'Owned short-lived SFN encryption admission probe'}))
    OWNED['roles'].append(role_name)
    CAP['actors'][name] = {'role_name': role_name, 'role_arn': output['Role']['Arn'], 'trust_policy': trust, 'inline_policy_name': 'immutable-probe', 'inline_policy': policy, 'session_policy': None, 'session_name': None, 'identity': None}
    must(call('setup-policy-' + name, 'iam', 'put-role-policy', {'RoleName': role_name, 'PolicyName': 'immutable-probe', 'PolicyDocument': json.dumps(policy)}))
    return output['Role']['Arn']


def setup():
    identity = must(call('caller-identity', 'sts', 'get-caller-identity'))
    assert identity['Account'] == ACCOUNT
    CAP['caller_arn'] = identity['Arn']
    CAP['actors']['default'] = {'identity': identity, 'credential_source': 'AWS_PROFILE=default', 'session_policy': None, 'authority': 'Existing delegated probe identity; its preexisting policies were not modified.'}
    key_policy = {'Version': '2012-10-17', 'Statement': [{'Sid': 'EnableOwnedAccountIAM', 'Effect': 'Allow', 'Principal': {'AWS': 'arn:aws:iam::' + ACCOUNT + ':root'}, 'Action': 'kms:*', 'Resource': '*'}]}
    CAP['key_policy'] = key_policy
    for key in ('old', 'new', 'asymmetric'):
        params = {'Description': PREFIX + '-' + key, 'Policy': json.dumps(key_policy), 'KeyUsage': 'ENCRYPT_DECRYPT', 'KeySpec': 'RSA_2048' if key == 'asymmetric' else 'SYMMETRIC_DEFAULT', 'Tags': [{'TagKey': 'probe', 'TagValue': PREFIX}]}
        metadata = must(call('setup-key-' + key, 'kms', 'create-key', params))['KeyMetadata']
        KEYS[key] = metadata
        OWNED['keys'].append(metadata['Arn'])
        save()
    alias = 'alias/' + PREFIX
    must(call('setup-alias', 'kms', 'create-alias', {'AliasName': alias, 'TargetKeyId': KEYS['old']['KeyId']}))
    OWNED['aliases'].append(alias)
    ARNS['alias'] = alias
    ARNS['alias_arn'] = 'arn:aws:kms:' + REGION + ':' + ACCOUNT + ':' + alias
    key_arns = [KEYS[k]['Arn'] for k in ('old', 'new')]
    execution_policy = {'Version': '2012-10-17', 'Statement': [{'Effect': 'Allow', 'Action': ['kms:Decrypt', 'kms:GenerateDataKey'], 'Resource': key_arns}, {'Effect': 'Allow', 'Action': ['states:StartExecution', 'states:DescribeExecution', 'states:StopExecution'], 'Resource': ['arn:aws:states:' + REGION + ':' + ACCOUNT + ':stateMachine:' + PREFIX + '*', 'arn:aws:states:' + REGION + ':' + ACCOUNT + ':execution:' + PREFIX + '*']}]}
    ARNS['execution_role'] = role('execution', {'Service': 'states.amazonaws.com'}, execution_policy)
    common = [{'Effect': 'Allow', 'Action': 'states:*', 'Resource': ['arn:aws:states:' + REGION + ':' + ACCOUNT + ':stateMachine:' + PREFIX + '*', 'arn:aws:states:' + REGION + ':' + ACCOUNT + ':execution:' + PREFIX + '*', 'arn:aws:states:' + REGION + ':' + ACCOUNT + ':activity:' + PREFIX + '*', 'arn:aws:states:' + REGION + ':' + ACCOUNT + ':mapRun:' + PREFIX + '*']}, {'Effect': 'Allow', 'Action': 'iam:PassRole', 'Resource': ARNS['execution_role']}, {'Effect': 'Allow', 'Action': ['kms:DescribeKey', 'kms:GenerateDataKey', 'kms:Decrypt'], 'Resource': key_arns}]
    controls = {'full': None, 'denyDescribe': 'kms:DescribeKey', 'denyGenerate': 'kms:GenerateDataKey', 'denyDecrypt': 'kms:Decrypt', 'noKms': 'kms:*', 'onlyOld': None, 'onlyNew': None, 'viaService': None}
    for actor, deny in controls.items():
        statements = copy.deepcopy(common)
        if deny:
            statements.append({'Effect': 'Deny', 'Action': deny, 'Resource': key_arns})
        if actor in ('onlyOld', 'onlyNew'):
            statements.append({'Effect': 'Deny', 'Action': 'kms:*', 'Resource': KEYS['new' if actor == 'onlyOld' else 'old']['Arn']})
        if actor == 'viaService':
            statements[2]['Condition'] = {'StringEquals': {'kms:ViaService': 'states.' + REGION + '.amazonaws.com'}}
        policy = {'Version': '2012-10-17', 'Statement': statements}
        role(actor, {'AWS': identity['Arn']}, policy)
    time.sleep(12)
    for actor in controls:
        actor_config = CAP['actors'][actor]
        session = 'admission-' + actor
        actor_config.update(session_name=session, session_policy=actor_config['inline_policy'])
        for attempt in range(4):
            response = call('setup-assume-' + actor + '-' + str(attempt), 'sts', 'assume-role', {'RoleArn': actor_config['role_arn'], 'RoleSessionName': session, 'DurationSeconds': 3600, 'Policy': json.dumps(actor_config['session_policy'])})
            if response['code'] == 'Success':
                break
            time.sleep(5)
        output = must(response)
        credentials = output['Credentials']
        actor_env = {k: v for k, v in ENV.items() if k not in ('AWS_PROFILE', 'AWS_DEFAULT_PROFILE', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'AWS_SESSION_TOKEN')}
        actor_env.update(AWS_ACCESS_KEY_ID=credentials['AccessKeyId'], AWS_SECRET_ACCESS_KEY=credentials['SecretAccessKey'], AWS_SESSION_TOKEN=credentials['SessionToken'])
        ENVS[actor] = actor_env
        actor_config['assumed_role_user'] = output['AssumedRoleUser']
        actor_config['identity'] = must(call('identity-' + actor, 'sts', 'get-caller-identity', actor=actor))
    save()


def canonicalization():
    for suffix, identifier in (('id', KEYS['old']['KeyId']), ('arn', KEYS['old']['Arn']), ('alias', ARNS['alias']), ('aliasarn', ARNS['alias_arn'])):
        label = 'standard-' + suffix
        create(label, enc(identifier), publish=suffix == 'id')
        describe(label + '-describe', ARNS[label])
        alabel = 'activity-' + suffix
        create(alabel, enc(identifier), kind='ACTIVITY')
        call(alabel + '-describe', 'stepfunctions', 'describe-activity', {'activityArn': ARNS[alabel]})
    create('express-alias', enc(ARNS['alias']), kind='EXPRESS')
    describe('express-describe', ARNS['express-alias'])
    create('plain-standard')
    describe('plain-standard-describe', ARNS['plain-standard'])
    create('plain-activity', kind='ACTIVITY')
    call('plain-activity-describe', 'stepfunctions', 'describe-activity', {'activityArn': ARNS['plain-activity']})
    for suffix, identifier in (('id', KEYS['old']['KeyId']), ('arn', KEYS['old']['Arn']), ('alias', ARNS['alias']), ('aliasarn', ARNS['alias_arn'])):
        create('idempotent-standard-' + suffix, enc(identifier), name=PREFIX + '-standard-id', publish=True)
        create('idempotent-activity-' + suffix, enc(identifier), name=PREFIX + '-activity-id', kind='ACTIVITY')
    for suffix, config in (('default300', enc('old', 300)), ('reuse60', enc('old', 60)), ('differentkey', enc('new')), ('reset', {'type': 'AWS_OWNED_KEY'}), ('omit', None)):
        create('idempotent-standard-' + suffix, config, name=PREFIX + '-standard-id', publish=True)
        create('idempotent-activity-' + suffix, config, name=PREFIX + '-activity-id', kind='ACTIVITY')


def validation():
    cases = [('missingkey', {'type': 'CUSTOMER_MANAGED_KMS_KEY'}), ('emptykey', enc('')), ('unknownkey', enc('arn:aws:kms:' + REGION + ':' + ACCOUNT + ':key/00000000-0000-0000-0000-000000000001')), ('asymmetric', enc('asymmetric')), ('reuse59', enc('old', 59)), ('reuse901', enc('old', 901)), ('reuse60', enc('old', 60)), ('reuse900', enc('old', 900)), ('owned-keyfield', {'type': 'AWS_OWNED_KEY', 'kmsKeyId': KEYS['old']['Arn']}), ('owned-reuse', {'type': 'AWS_OWNED_KEY', 'kmsDataKeyReusePeriodSeconds': 300}), ('unknown-type', {'type': 'SYNTHETIC_UNKNOWN'})]
    for name, config in cases:
        for kind in ('STANDARD', 'ACTIVITY'):
            label = 'validation-' + kind.lower() + '-' + name
            response = create(label, config, kind=kind)
            if response['code'] == 'Success':
                if kind == 'ACTIVITY':
                    call(label + '-describe', 'stepfunctions', 'describe-activity', {'activityArn': ARNS[label]})
                else:
                    describe(label + '-describe', ARNS[label])
    for name, config in cases[:6]:
        create('validation-express-' + name, config, kind='EXPRESS')


def authority():
    for actor in ('full', 'denyDescribe', 'denyGenerate', 'denyDecrypt', 'noKms', 'viaService'):
        call('direct-describekey-' + actor, 'kms', 'describe-key', {'KeyId': KEYS['old']['Arn']}, actor)
        create('authority-standard-' + actor.lower(), enc(), actor)
        create('authority-activity-' + actor.lower(), enc(), actor, kind='ACTIVITY')
        for included in (None, 'ALL_DATA', 'METADATA_ONLY'):
            describe('read-standard-' + actor + '-' + str(included), ARNS['standard-id'], actor, included)
            describe('read-express-' + actor + '-' + str(included), ARNS['express-alias'], actor, included)
        call('read-activity-' + actor, 'stepfunctions', 'describe-activity', {'activityArn': ARNS['activity-id']}, actor)
    for actor in ('full', 'denyDescribe', 'denyGenerate', 'denyDecrypt', 'noKms', 'viaService'):
        call('update-definition-' + actor, 'stepfunctions', 'update-state-machine', {'stateMachineArn': ARNS['standard-arn'], 'definition': NEW_DEF}, actor)
        call('update-encryption-' + actor, 'stepfunctions', 'update-state-machine', {'stateMachineArn': ARNS['standard-arn'], 'encryptionConfiguration': enc('old', 60)}, actor)
    create('read-map', enc(), definition=MAP_DEF)
    for actor in ('full', 'denyDecrypt', 'noKms'):
        for included in ('ALL_DATA', 'METADATA_ONLY'):
            describe('labelled-map-' + actor + '-' + included, ARNS['read-map'] + '/NativeLabel', actor, included)
    execution = must(call('start-retained-old-execution', 'stepfunctions', 'start-execution', {'stateMachineArn': ARNS['standard-id'] + ':1', 'name': PREFIX + '-retained-old', 'input': '{"synthetic":true}'}))['executionArn']
    OWNED['executions'].append(execution)
    ARNS['old_execution'] = execution
    for attempt in range(10):
        response = describe('execution-definition-ready-' + str(attempt), execution, execution=True)
        if response['code'] == 'Success':
            break
        time.sleep(2)
    for actor in ('full', 'denyDecrypt', 'noKms'):
        for included in (None, 'ALL_DATA', 'METADATA_ONLY'):
            describe('execution-definition-' + actor + '-' + str(included), execution, actor, included, execution=True)


def retained():
    arn = ARNS['standard-id']
    call('update-reuse-to60', 'stepfunctions', 'update-state-machine', {'stateMachineArn': arn, 'encryptionConfiguration': enc('old', 60)})
    describe('after-update-reuse-to60', arn)
    call('update-omit-encryption', 'stepfunctions', 'update-state-machine', {'stateMachineArn': arn, 'definition': NEW_DEF})
    describe('after-update-omit-encryption', arn)
    call('update-samekey-omit-reuse', 'stepfunctions', 'update-state-machine', {'stateMachineArn': arn, 'encryptionConfiguration': enc()})
    describe('after-update-samekey-omit-reuse', arn)
    response = must(call('update-newkey-publish', 'stepfunctions', 'update-state-machine', {'stateMachineArn': arn, 'encryptionConfiguration': enc('new', 60), 'definition': NEW_DEF, 'publish': True}))
    ARNS['new_version'] = response['stateMachineVersionArn']
    for stage in ('immediate', 'settled'):
        if stage == 'settled':
            time.sleep(8)
        for actor in ('onlyOld', 'onlyNew', 'full', 'noKms'):
            for label, target, execution in (('latest', arn, False), ('oldversion', arn + ':1', False), ('newversion', ARNS['new_version'], False), ('oldexecution', ARNS['old_execution'], True)):
                describe('retained-' + stage + '-' + label + '-' + actor, target, actor, 'ALL_DATA', execution)
                if stage == 'settled' and actor == 'noKms':
                    describe('retained-metadata-' + label, target, actor, 'METADATA_ONLY', execution)
    call('reset-aws-owned', 'stepfunctions', 'update-state-machine', {'stateMachineArn': arn, 'encryptionConfiguration': {'type': 'AWS_OWNED_KEY'}})
    for included in ('ALL_DATA', 'METADATA_ONLY'):
        describe('reset-latest-noKms-' + included, arn, 'noKms', included)
    describe('reset-retained-newversion-noKms', ARNS['new_version'], 'noKms', 'ALL_DATA')
    call('update-express-newkey', 'stepfunctions', 'update-state-machine', {'stateMachineArn': ARNS['express-alias'], 'encryptionConfiguration': enc('new')})
    describe('updated-express-newkey', ARNS['express-alias'], 'onlyNew')
    call('reset-express-owned', 'stepfunctions', 'update-state-machine', {'stateMachineArn': ARNS['express-alias'], 'encryptionConfiguration': {'type': 'AWS_OWNED_KEY'}})
    describe('reset-express-noKms', ARNS['express-alias'], 'noKms')


def disabled():
    must(call('disable-old-key', 'kms', 'disable-key', {'KeyId': KEYS['old']['Arn']}))
    call('disabled-key-state', 'kms', 'describe-key', {'KeyId': KEYS['old']['Arn']})
    for phase in ('immediate', 'settled'):
        if phase == 'settled':
            time.sleep(8)
        for kind in ('STANDARD', 'EXPRESS', 'ACTIVITY'):
            create('disabled-' + phase + '-' + kind.lower(), enc(), kind=kind)
        for label, target, execution in (('retained-version', ARNS['standard-id'] + ':1', False), ('existing', ARNS['standard-alias'], False), ('retained-execution', ARNS['old_execution'], True)):
            for included in ('ALL_DATA', 'METADATA_ONLY'):
                describe('disabled-' + phase + '-' + label + '-' + included, target, 'full', included, execution)
        call('disabled-' + phase + '-activity-metadata', 'stepfunctions', 'describe-activity', {'activityArn': ARNS['activity-id']}, 'noKms')
    call('disabled-update-oldkey', 'stepfunctions', 'update-state-machine', {'stateMachineArn': ARNS['standard-alias'], 'definition': NEW_DEF})
    call('disabled-update-newkey-without-old-authority', 'stepfunctions', 'update-state-machine', {'stateMachineArn': ARNS['standard-alias'], 'encryptionConfiguration': enc('new')}, 'onlyNew')
    call('disabled-reset-owned-noKms', 'stepfunctions', 'update-state-machine', {'stateMachineArn': ARNS['standard-aliasarn'], 'encryptionConfiguration': {'type': 'AWS_OWNED_KEY'}}, 'noKms')
    describe('disabled-reset-owned-result', ARNS['standard-aliasarn'], 'noKms')


def history():
    for key in ('old', 'new', 'asymmetric'):
        token = None
        for page in range(6):
            params = {'LookupAttributes': [{'AttributeKey': 'ResourceName', 'AttributeValue': KEYS[key]['KeyId']}], 'StartTime': CAP['started_at'], 'MaxResults': 50}
            if token:
                params['NextToken'] = token
            response = call('cloudtrail-' + key + '-' + str(page), 'cloudtrail', 'lookup-events', params)
            if response['code'] != 'Success':
                break
            token = response['output'].get('NextToken')
            if not token:
                break
            time.sleep(0.6)
    CAP['notes'].append('CloudTrail history is a bounded available-event snapshot, not proof that absent calls did not occur. AccessKeyId fields redacted; requestID, user ARN, assumed role/session issuer and encryption contexts retained.')
    save()


def cleanup():
    for execution in OWNED['executions']:
        response = call('cleanup-execution-status-' + execution.rsplit(':', 1)[-1], 'stepfunctions', 'describe-execution', {'executionArn': execution, 'includedData': 'METADATA_ONLY'})
        if response['code'] == 'Success' and response['output'].get('status') == 'RUNNING':
            call('cleanup-stop-execution', 'stepfunctions', 'stop-execution', {'executionArn': execution})
    for arn in OWNED['machines']:
        call('cleanup-delete-machine-' + arn.rsplit(':', 1)[-1], 'stepfunctions', 'delete-state-machine', {'stateMachineArn': arn})
    for arn in OWNED['activities']:
        call('cleanup-delete-activity-' + arn.rsplit(':', 1)[-1], 'stepfunctions', 'delete-activity', {'activityArn': arn})
    for name in OWNED['roles']:
        call('cleanup-delete-role-policy-' + name, 'iam', 'delete-role-policy', {'RoleName': name, 'PolicyName': 'immutable-probe'})
        call('cleanup-delete-role-' + name, 'iam', 'delete-role', {'RoleName': name})
    for alias in OWNED['aliases']:
        call('cleanup-delete-alias', 'kms', 'delete-alias', {'AliasName': alias})
    for arn in OWNED['keys']:
        call('cleanup-schedule-key-deletion-' + arn.rsplit('/', 1)[-1], 'kms', 'schedule-key-deletion', {'KeyId': arn, 'PendingWindowInDays': 7})
    checks = {'machines': {}, 'activities': {}, 'roles': {}, 'aliases': {}, 'keys': {}}
    for arn in OWNED['machines']:
        response = describe('cleanup-verify-machine-' + arn.rsplit(':', 1)[-1], arn, included='METADATA_ONLY')
        checks['machines'][arn] = response
    for arn in OWNED['activities']:
        checks['activities'][arn] = call('cleanup-verify-activity-' + arn.rsplit(':', 1)[-1], 'stepfunctions', 'describe-activity', {'activityArn': arn})
    for name in OWNED['roles']:
        checks['roles'][name] = call('cleanup-verify-role-' + name, 'iam', 'get-role', {'RoleName': name})
    for alias in OWNED['aliases']:
        checks['aliases'][alias] = call('cleanup-verify-alias', 'kms', 'describe-key', {'KeyId': alias})
    for arn in OWNED['keys']:
        checks['keys'][arn] = call('cleanup-verify-key-' + arn.rsplit('/', 1)[-1], 'kms', 'describe-key', {'KeyId': arn})
    deadline = time.monotonic() + 150
    for attempt in range(20):
        pending = [arn for arn, response in checks['machines'].items() if response['code'] != 'StateMachineDoesNotExist']
        if not pending or time.monotonic() > deadline:
            break
        time.sleep(5)
        for arn in pending:
            checks['machines'][arn] = describe('cleanup-verify-machine-retry-' + str(attempt) + '-' + arn.rsplit(':', 1)[-1], arn, included='METADATA_ONLY')
    CAP['cleanup'] = redact(checks)
    CAP['finished_at'] = datetime.now(timezone.utc).isoformat()
    CAP['notes'].append('CMKs are not deleted immediately: cleanup schedules the AWS minimum 7-day window and independently describes PendingDeletion state. AWS may retain closed execution history after machine deletion; synthetic execution data was used.')
    save()


def main():
    try:
        setup()
        canonicalization()
        validation()
        authority()
        retained()
        disabled()
        history()
    finally:
        cleanup()

if __name__ == '__main__':
    main()

"""AWS CLI transport shared by native behavior probes.

Callers own endpoint/retry choices, observations and resource cleanup. JSON shapes
remain open because probes deliberately exercise invalid and newly added inputs.
"""
import ast
import json
import re
import subprocess
from collections.abc import Mapping, Sequence
from typing import Any, NotRequired, TypedDict


class ProbeResult(TypedDict):
    code: str
    output: NotRequired[dict[str, Any]]
    error: NotRequired[dict[str, Any]]
    message: NotRequired[str]
    http_status: NotRequired[int]


class CLITimeout(RuntimeError):
    """A bounded CLI call expired; command arguments may contain secrets."""


class AWSCLIError(RuntimeError):
    """A failed strict call, retaining native JSON error fields for its caller."""

    def __init__(self, service: str, operation: str, stderr: str, details: dict[str, Any]):
        super().__init__(f"{service}:{operation}: {stderr.strip()}")
        self.details = details


def run(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
        env: Mapping[str, str] | None = None, *, options: Sequence[str] = (),
        timeout: float | None = None) -> subprocess.CompletedProcess[str]:
    """Execute one CLI command without interpreting service or client failures."""
    command = ["aws", service, operation, "--output", "json", "--no-cli-pager"]
    if parameters is not None:
        command += ["--cli-input-json", json.dumps(parameters)]
    try:
        return subprocess.run(command + list(options), env=env, capture_output=True,
                              text=True, check=False, timeout=timeout)
    except subprocess.TimeoutExpired:
        raise CLITimeout("AWS CLI timed out during " + operation) from None


def call(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
         env: Mapping[str, str] | None = None, *, paginate: bool = True,
         error_format: str | None = None) -> dict[str, Any]:
    """Return JSON output; service and CLI-validation errors retain typed details.

    Configuration and transport failures abort capture instead of becoming
    observations of AWS behavior. AWS CLI uses 252 for input errors and 254
    for service errors.
    """
    options = ["--cli-connect-timeout", "10", "--cli-read-timeout", "30"]
    if error_format is not None:
        options += ["--cli-error-format", error_format]
    if not paginate:
        options.append("--no-paginate")
    process = run(service, operation, parameters or None, env, options=options)
    if process.returncode:
        diagnosis = f"{service}:{operation}: {process.stderr.strip()}"
        if error_format == "json" and process.returncode in (252, 254):
            try:
                details = json.loads(process.stderr)
            except json.JSONDecodeError:
                raise RuntimeError(diagnosis) from None
            if isinstance(details, dict) and isinstance(details.get("Code"), str):
                raise AWSCLIError(service, operation, process.stderr, details)
        raise RuntimeError(diagnosis)
    return result(process)["output"]


def observe(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
            env: Mapping[str, str] | None = None, *, paginate: bool = True) -> ProbeResult:
    """Capture native JSON success/error fields; callers own output redaction."""
    try:
        output = call(service, operation, parameters, env, paginate=paginate, error_format="json")
    except AWSCLIError as error:
        return {"code": error.details["Code"], "error": error.details}
    return {"code": "Success", "output": output}


def _text_error(stderr: str) -> tuple[str, str | None]:
    match = re.search(r"An error occurred \(([^)]+)\)(?:.*?operation(?: \([^)]*\))?: (.*))?", stderr)
    return (match[1], match[2]) if match else ("CLIError", None)


def result(process: subprocess.CompletedProcess[str], *, cli_error: str = "CLIError",
           cli_message: str | None = "AWS CLI failed; raw diagnostics discarded",
           debug: bool = False) -> ProbeResult:
    """Decode an observation, separating modeled errors from CLI rejection.

    A None client message retains the final three diagnostic lines for probes
    whose captured CLI-validation observations include those lines.
    """
    if process.returncode:
        code, message = _text_error(process.stderr)
        decoded: ProbeResult = {
            "code": code if message is not None else cli_error,
            "message": message if message is not None else cli_message if cli_message is not None
            else " ".join(process.stderr.splitlines()[-3:]),
        }
    else:
        decoded = {"code": "Success", "output": json.loads(process.stdout) if process.stdout.strip() else {}}
    if debug:
        statuses = re.findall(r'"[A-Z]+ [^"\r\n]* HTTP/1\.[01]" (\d{3})', process.stderr)
        if statuses:
            decoded["http_status"] = int(statuses[-1])
    return decoded


def error_code(process: subprocess.CompletedProcess[str]) -> str:
    """Decode code-only observations, including CLI ParamValidation errors."""
    return _text_error(process.stderr)[0]


def raw_xml(process: subprocess.CompletedProcess[str]) -> bytes | None:
    """Extract the last XML response from CLI debug output; discard other logs."""
    raw = None
    for line in process.stderr.splitlines():
        if line.startswith(("b'<", 'b"<')):
            try:
                candidate = ast.literal_eval(line)
                if candidate.startswith(b"<"):
                    raw = candidate
            except (ValueError, SyntaxError):
                pass
    return raw

